<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Neon Neuron Growth</title>
<script src="https://cdn.jsdelivr.net/npm/dat.gui@0.7.9/build/dat.gui.min.js"></script>
<style>
  /* ---- Page chrome: dark backdrop, centered canvas ---- */
  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    background: #05070f;
    overflow: hidden;
    font-family: "Segoe UI", monospace, sans-serif;
  }
  #stage {
    position: fixed;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #frame {
    position: relative;
    width: 800px;
    height: 800px;
  }
  canvas {
    display: block;
    width: 800px;
    height: 800px;
    background: #05070f;
    border: 1px solid rgba(0, 229, 255, 0.25);
    box-shadow: 0 0 40px rgba(0, 229, 255, 0.15),
                0 0 120px rgba(16, 26, 58, 0.9),
                inset 0 0 60px rgba(5, 7, 15, 0.9);
  }
  /* Faint CRT scanlines drawn with CSS gradient (no images) */
  #scanlines {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: repeating-linear-gradient(
      to bottom,
      rgba(0, 229, 255, 0.08) 0px,
      rgba(0, 229, 255, 0.08) 1px,
      transparent 1px,
      transparent 4px
    );
    mix-blend-mode: screen;
